WITH flattened AS (SELECT id, plan, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) e AS element) SELECT id, plan, CUME_DIST() OVER (PARTITION BY plan ORDER BY element NULLS LAST) AS element_cume_dist, MIN(element) OVER w_recent AS plan_min_element, MAX(element) OVER w_recent AS plan_max_element FROM flattened WHERE plan = 'enterprise' WINDOW w_recent AS (PARTITION BY plan);
